แน่นอน! ด้านล่างนี้คือโค้ดสำหรับ Discord Bot ที่ใช้ **Discord.js v14** โดยมีคำสั่งเดียวคือ `/ban` (Slash Command) เพื่อระงับผู้ใช้ (ban) ออกจากเซิร์ฟเวอร์

---

### 📁 โครงสร้างไฟล์
```
bot/
├── index.js
├── deploy-commands.js
```

---

### ✅ ขั้นตอนการติดตั้ง
1. ติดตั้ง Discord.js
```bash
npm install discord.js@14
```

2. สร้างไฟล์ `index.js` และ `deploy-commands.js`

---

## ✅ 1. `deploy-commands.js` – ใช้สำหรับลงทะเบียน Slash Command

```js
const { REST, Routes } = require('discord.js');
const { clientId, guildId, token } = require('./config.json');

const commands = [
  {
    name: 'ban',
    description: 'Ban a member from the server',
    options: [
      {
        name: 'user',
        type: 6, // USER type
        description: 'The user to ban',
        required: true,
      },
      {
        name: 'reason',
        type: 3, // STRING type
        description: 'Reason for the ban',
        required: false,
      },
    ],
  },
];

const rest = new REST({ version: '10' }).setToken(token);

(async () => {
  try {
    console.log('Started refreshing application (/) commands.');

    await rest.put(
      Routes.applicationGuildCommands(clientId, guildId),
      { body: commands }
    );

    console.log('Successfully reloaded application (/) commands.');
  } catch (error) {
    console.error(error);
  }
})();
```

---

## ✅ 2. `index.js` – โค้ดหลักของบอท

```js
const { Client, GatewayIntentBits, Collection } = require('discord.js');
const { clientId, guildId, token } = require('./config.json');

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
  ],
});

client.commands = new Collection();

// ฟังก์ชันเพื่อจัดการคำสั่ง /ban
client.on('interactionCreate', async interaction => {
  if (!interaction.isChatInputCommand()) return;

  if (interaction.commandName === 'ban') {
    // ตรวจสอบว่าผู้ใช้มีสิทธิ์ ban หรือไม่
    if (!interaction.member.permissions.has('BanMembers')) {
      return interaction.reply({
        content: '❌ คุณไม่มีสิทธิ์ในการใช้คำสั่งนี้',
        ephemeral: true,
      });
    }

    const user = interaction.options.getUser('user');
    const reason = interaction.options.getString('reason') || 'ไม่ระบุเหตุผล';
    const member = await interaction.guild.members.fetch(user.id).catch(() => null);

    // ตรวจสอบว่าบอทมีสิทธิ์ ban หรือไม่
    if (!interaction.guild.members.me.permissions.has('BanMembers')) {
      return interaction.reply({
        content: '❌ บอทไม่มีสิทธิ์ในการระงับผู้ใช้',
        ephemeral: true,
      });
    }

    // ห้ามบอท ban ตัวเอง
    if (user.id === client.user.id) {
      return interaction.reply({
        content: '❌ ฉันห้ามระงับตัวเองนะ!',
        ephemeral: true,
      });
    }

    // ตรวจสอบสมาชิกที่ต้องการ ban
    if (!member) {
      return interaction.reply({
        content: '❌ ไม่พบผู้ใช้ในเซิร์ฟเวอร์นี้',
        ephemeral: true,
      });
    }

    // ห้าม ban ผู้ใช้ที่มีบทบาทสูงกว่าหรือเท่ากับบอท
    if (member.roles.highest.position >= interaction.guild.members.me.roles.highest.position) {
      return interaction.reply({
        content: '❌ ฉันไม่สามารถระงับผู้ใช้ที่มีบทบาทสูงกว่าหรือเท่ากับฉันได้',
        ephemeral: true,
      });
    }

    try {
      await member.ban({ reason });
      await interaction.reply({
        content: `✅ ผู้ใช้ ${user.tag} ถูกระงับเรียบร้อยแล้ว | เหตุผล: ${reason}`,
      });
    } catch (error) {
      console.error(error);
      await interaction.reply({
        content: '❌ เกิดข้อผิดพลาดในการระงับผู้ใช้',
        ephemeral: true,
      });
    }
  }
});

client.once('ready', () => {
  console.log(`🟢 บอท ${client.user.tag} เริ่มทำงานแล้ว!`);
});

client.login(token);
```

---

## ✅ 3. `config.json` – สำหรับเก็บข้อมูลสำคัญ

```json
{
  "token": "YOUR_BOT_TOKEN_HERE",
  "clientId": "YOUR_BOT_CLIENT_ID",
  "guildId": "YOUR_SERVER_GUILD_ID"
}
```

> 🔐 อย่าลืมแทนที่ด้วยข้อมูลจริงของคุณ และ **ห้ามอัปโหลดไฟล์นี้ขึ้น GitHub** หากคุณใช้ public repository (ให้ใช้ `.env` แทนใน Production)

---

### ✅ วิธีใช้งาน

1. รันคำสั่งเพื่อลงทะเบียนคำสั่ง:
```bash
node deploy-commands.js
```

2. รันบอท:
```bash
node index.js
```

3. พิมพ์ใน Discord: `/ban user:@user reason:สแปม` เพื่อระงับผู้ใช้

---

### ✅ หมายเหตุสำคัญ

- ต้องเปิดใช้งาน **Privileged Gateway Intents** ใน [Discord Developer Portal](https://discord.com/developers/applications)
- ต้องให้บอทมีบทบาทที่สิทธิ์ `Ban Members` และ `Manage Roles` (ถ้าจำเป็น)
- คำสั่งนี้ใช้ได้เฉพาะในเซิร์ฟเวอร์ที่กำหนดใน `guildId` (เฉพาะใช้กับเซิร์ฟเวอร์เดียว)

---

หากต้องการให้ใช้ได้ทุกเซิร์ฟเวอร์ (global commands) ให้ใช้ `Routes.applicationCommands(clientId)` แทน `Routes.applicationGuildCommands(...)`

ต้องการเวอร์ชันที่ใช้ `.env` หรือ database ไหม? แจ้งได้นะครับ 😊

นี่คือฟังก์ชัน JavaScript ที่รับอาร์เรย์ของตัวเลข 5 ตัว และตรวจสอบว่าตัวเลขแต่ละตัวเป็น **จำนวนเฉพาะ (Prime Number)** หรือไม่ ถ้าเป็น ก็จะพิมพ์ตัวเลขนั้นลงในคอนโซล:

```javascript
function printPrimeNumbers(numbers) {
    // ตรวจสอบว่าอาร์เรย์มี 5 ตัวหรือไม่
    if (!Array.isArray(numbers) || numbers.length !== 5) {
        console.log("กรุณาใส่อาร์เรย์ที่มีตัวเลขทั้งหมด 5 ตัว");
        return;
    }

    // ฟังก์ชันตรวจสอบจำนวนเฉพาะ
    function isPrime(num) {
        if (num < 2) return false;
        if (num === 2) return true;
        if (num % 2 === 0) return false;

        // ตรวจสอบตัวหารจาก 3 ถึง √num (เฉพาะเลขคี่)
        for (let i = 3; i <= Math.sqrt(num); i += 2) {
            if (num % i === 0) return false;
        }
        return true;
    }

    // ตรวจสอบแต่ละตัวในอาร์เรย์
    for (let i = 0; i < numbers.length; i++) {
        const num = numbers[i];
        // ตรวจสอบว่าเป็นตัวเลขหรือไม่
        if (typeof num !== 'number' || !Number.isInteger(num)) {
            console.log(`${num} ไม่ใช่จำนวนเต็ม`);
            continue;
        }

        if (isPrime(num)) {
            console.log(num);
        }
    }
}

// ตัวอย่างการใช้งาน
printPrimeNumbers([2, 3, 4, 5, 6]); // ผลลัพธ์ที่พิมพ์: 2, 3, 5
printPrimeNumbers([10, 11, 12, 13, 14]); // ผลลัพธ์ที่พิมพ์: 11, 13
```

### คำอธิบาย:
- `isPrime(num)`: ฟังก์ชันย่อยที่ตรวจสอบว่า `num` เป็นจำนวนเฉพาะหรือไม่
- ใช้ `Math.sqrt(num)` เพื่อลดจำนวนรอบในการวนลูป
- ตรวจสอบว่าแต่ละตัวในอาร์เรย์เป็นจำนวนเต็มหรือไม่ก่อน
- พิมพ์เฉพาะตัวที่เป็นจำนวนเฉพาะ

### เงื่อนไข:
- ต้องเป็นจำนวนเต็มบวกที่มากกว่า 1
- มีตัวหารที่เป็นบวกได้แค่ 2 ตัว (คือ 1 และตัวมันเอง)

หากต้องการให้ฟังก์ชันรับข้อมูลจากผู้ใช้ หรือรับจากที่อื่นเพิ่มเติม สามารถปรับได้ตามต้องการครับ 😊

